-- Request-local chapter DTO reuse. The one-argument canonical projection is
-- unchanged. This overload preserves its exact fields and visibility predicate;
-- only already projected parent/group relationships are supplied by the same
-- feed statement. It is not a cross-request cache or an authority decision.
CREATE FUNCTION platform.catalog_chapter_json(value TEXT,parent_json JSONB,groups_json JSONB) RETURNS JSONB LANGUAGE SQL STABLE AS $$
 SELECT jsonb_strip_nulls(c.metadata || jsonb_build_object('id',c.id,'source_id',c.source_id,'created_at',platform.catalog_timestamp(c.created_at),'updated_at',platform.catalog_timestamp(c.updated_at),'published_at',platform.catalog_timestamp(c.published_at),'deleted_at',platform.catalog_timestamp(c.deleted_at),'title',c.title,'volume',c.volume,'chapter',c.chapter,'language',c.language,'is_unavailable',c.is_unavailable,'version',c.version,'relationships',jsonb_build_object('uploader',jsonb_build_object('id',c.uploader_id,'name',c.uploader_name,'version',1),'manga',parent_json,'groups',groups_json,'thread',platform.catalog_thread_json('chapter',c.id),'stats',jsonb_build_object('views',COALESCE(s.views,0))))) FROM platform.catalog_chapters c LEFT JOIN platform.catalog_chapter_counters s ON s.chapter_id=c.id WHERE c.id=value AND c.deleted_at IS NULL AND platform.protocol_source_is_visible(c.protocol_event_id) AND EXISTS(SELECT 1 FROM platform.catalog_manga parent WHERE parent.id=c.manga_id AND parent.deleted_at IS NULL AND parent.state='published' AND parent.protocol_source_visible AND platform.protocol_source_is_visible(parent.protocol_series_id))
$$;
